    /// <summary>Windows XP Luna colour scheme.</summary>
    public enum LunaColorScheme
    {
        Blue,
        Olive,
        Silver
    }

    /// <summary>
    /// A complete set of explicit RGB colour definitions from one XP Luna
    /// Normal*.INI resource. Keys use the original section and property names.
    /// If a section defines the same property more than once, [2], [3], etc.
    /// preserve the original occurrence rather than silently overwriting it.
    /// </summary>
    public sealed class LunaPalette
    {
        private readonly IReadOnlyDictionary<string, Color> _colors;

        internal LunaPalette(string name, IReadOnlyDictionary<string, Color> colors)
        {
            Name = name;
            _colors = colors;
        }

        public string Name { get; }

        /// <summary>All explicit RGB colour definitions in the source style resource.</summary>
        public IReadOnlyDictionary<string, Color> Colors => _colors;

        /// <summary>Gets a colour using its original resource path, e.g. Window.TextShadowColor.</summary>
        public Color this[string resourceName] => _colors[resourceName];

        public bool TryGetColor(string resourceName, out Color color) =>
            _colors.TryGetValue(resourceName, out color);

        // Frequently useful semantic aliases.
        public Color EdgeLight => Get("globals.EdgeLightColor");
        public Color EdgeHighlight => Get("globals.EdgeHighLightColor");
        public Color EdgeShadow => Get("globals.EdgeShadowColor");
        public Color EdgeDarkShadow => Get("globals.EdgeDkShadowColor");
        public Color EdgeFill => Get("globals.EdgeFillColor");
        public Color Text => Get("button.pushbutton.TextColor");
        public Color DisabledText => Get("button.pushbutton(disabled).TextColor");
        public Color GroupBoxText => Get("button.groupbox.TextColor");
        public Color Control => TryGetColor("SysMetrics.Btnface", out var face) ? face : EdgeFill;
        public Color ControlDisabled => Get("edit.edittext(Disabled).FillColor");
        public Color EditFill => Get("edit.FillColor");
        public Color ControlBorder => Get("edit.BorderColor");
        public Color ListBoxBorder => Get("Listbox.BorderColor");
        public Color ListBoxFill => Get("Listbox.FillColor");
        public Color ListViewBorder => Get("ListView.BorderColor");
        public Color ListViewFill => Get("ListView.FillColor");
        public Color TreeViewBorder => Get("TreeView.BorderColor");
        public Color TreeViewFill => Get("TreeView.FillColor");
        public Color ToolbarFill => Get("Toolbar.FillColor");
        public Color ToolbarText => Get("Toolbar.TextColor");
        public Color DialogFill => Get("Window.dialog.FillColor");
        public Color DialogBorder => Get("Window.dialog.BorderColor");
        public Color WindowTextShadow => Get("Window.TextShadowColor");
        public Color ExplorerBarNormalFill => Get("ExplorerBar.NormalGroupBackground.FillColor");
        public Color ExplorerBarNormalBorder => Get("ExplorerBar.NormalGroupBackground.BorderColor");
        public Color ExplorerBarNormalText => Get("ExplorerBar.NormalGroupBackground.TextColor");
        public Color ExplorerBarSpecialText => Get("ExplorerBar.SpecialGroupHead.TextColor");
        public Color ExplorerBarSpecialFill => Get("ExplorerBar.SpecialGroupHead.FillColor");
        public Color ButtonFace => Get("button.pushbutton.FillColorHint");
        public Color ButtonFace2 => Lighten(ButtonFace, 0.06f);
        public Color ButtonPressed => Darken(ButtonFace, 0.08f);
        public Color ButtonPressed2 => Darken(ButtonFace, 0.16f);
        public Color ButtonTracking => Get("button.pushbutton.AccentColorHint");
        public Color ButtonTracking2 => Lighten(ButtonTracking, 0.12f);
        public Color ButtonChecked => Get("button.pushbutton(defaulted).AccentColorHint");
        public Color ButtonChecked2 => Lighten(ButtonChecked, 0.08f);
        public Color ButtonBorder => Get("button.pushbutton.BorderColorHint");
        public Color ButtonHighlight => Get("button.pushbutton.AccentColorHint");
        public Color CaptionFill => Get("Window.Caption.FillColorHint");

        /// <summary>Gets the upper colour of the active XP caption gradient when available.</summary>
        public Color CaptionFill2 => TryGetColor("SysMetrics.GradientActiveCaption", out var color)
            ? color
            : Lighten(CaptionFill, 0.28f);

        public Color CaptionText => TryGetColor("SysMetrics.CaptionText", out var color) ? color : Color.White;

        public Color InactiveCaptionText => TryGetColor("SysMetrics.InactiveCaptionText", out var color) ? color : CaptionText;

        public Color InactiveCaptionFill => TryGetColor("SysMetrics.InactiveCaption", out var color) ? color : CaptionFill;

        public Color InactiveCaptionFill2 => TryGetColor("SysMetrics.GradientInactiveCaption", out var color)
            ? color
            : Lighten(InactiveCaptionFill, 0.15f);

        public Color Highlight => TryGetColor("SysMetrics.Highlight", out var color)
            ? color
            : TryGetColor("SysMetrics.MenuHilight", out color) ? color : ButtonTracking;

        public Color HighlightText => TryGetColor("SysMetrics.HighlightText", out var color) ? color : Color.White;

        public Color ToolTipFill => Get("Window.dialog.FillColor");
        public Color ToolTipText => Text;

        private Color Get(string resourceName) => _colors[resourceName];

        private static Color Lighten(Color color, float amount)
        {
            amount = amount < 0f ? 0f : (amount > 1f ? 1f : amount);
            return Color.FromArgb(color.A,
                color.R + (int)((255 - color.R) * amount),
                color.G + (int)((255 - color.G) * amount),
                color.B + (int)((255 - color.B) * amount));
        }

        private static Color Darken(Color color, float amount)
        {
            amount = amount < 0f ? 0f : (amount > 1f ? 1f : amount);
            return Color.FromArgb(color.A,
                (int)(color.R * (1f - amount)),
                (int)(color.G * (1f - amount)),
                (int)(color.B * (1f - amount)));
        }
    }
}
